# Repair leaked authoring-status labels without altering drainage targets.
def clean_links(text):
 def sub(match):
  label,ref=match.groups()
  if re.search(r'High\s*\||\bNew\b|nomenclature review',label):label=byid[ref]['name']
  return f'[{label}](#structure-{ref})'
 return re.sub(r'\[([^]]+)\]\(#structure-([^\s)]+)\)',sub,text)
